function parityBySlot(nums: number[]): number[] {
  const out = new Array(nums.length);
  let even = 0, odd = 1;
  for (const v of nums) {
    if (v % 2 === 0) { out[even] = v; even += 2; }
    else { out[odd] = v; odd += 2; }
  }
  return out;
}

