class Solution:
    def parityBySlot(self, nums: List[int]) -> List[int]:
        out = [0] * len(nums)
        even, odd = 0, 1
        for v in nums:
            if v % 2 == 0:
                out[even] = v
                even += 2
            else:
                out[odd] = v
                odd += 2
        return out

