function parityBySlot(nums: number[]): number[] {
  const a = nums.slice();
  let j = 1;
  for (let i = 0; i < a.length; i += 2) {
    if (a[i] % 2 === 0) continue;
    while (a[j] % 2 === 1) j += 2;
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

